def encode(self, src: Tensor, src_key_padding_mask: Optional[Tensor]=None) -> Tensor:
    x = self.position(self.src_embedding(src))
    return self.encoder(x, src_key_padding_mask)

def forward(self, x: Tensor) -> Tensor:
    x = x + self.pe[:, :x.size(1)].to(dtype=x.dtype)
    return self.dropout(x)

def forward(self, x: Tensor, src_key_padding_mask: Optional[Tensor]=None) -> Tensor:
    for layer in self.layers:
        x = layer(x, src_key_padding_mask=src_key_padding_mask)
    return x

def _split_heads(self, x: Tensor) -> Tensor:
    b, t, _ = x.shape
    return x.view(b, t, self.num_heads, self.d_head).transpose(1, 2).contiguous()

